import { z } from "zod";

/**
 * The lesson contract.
 *
 * Lesson JSON files are generated by `python lessons/build.py` — never edit
 * them by hand.  Each step carries a caption, the code line it explains, and a
 * snapshot of every data structure ("view") at that moment.
 */

const tone = z.string().optional();

const ArrayViewSchema = z.object({
  t: z.literal("array"),
  id: z.string(),
  title: z.string().optional(),
  cells: z.array(z.object({ v: z.string(), tone, n: z.number().optional() })),
  ptrs: z.array(z.object({ name: z.string(), at: z.number() })).optional(),
  ranges: z
    .array(z.object({ from: z.number(), to: z.number(), label: z.string().optional(), tone }))
    .optional(),
  bars: z.boolean().optional(),
  water: z.array(z.number()).optional(),
  pool: z.object({ from: z.number(), to: z.number(), h: z.number() }).optional(),
  box: z.object({ from: z.number(), to: z.number(), h: z.number() }).optional(),
  max: z.number().optional(),
  idx: z.boolean().optional(),
});

const MapViewSchema = z.object({
  t: z.literal("map"),
  id: z.string(),
  title: z.string().optional(),
  kind: z.enum(["map", "set"]),
  entries: z.array(z.object({ k: z.string(), v: z.string().optional(), tone })),
});

const StackViewSchema = z.object({
  t: z.literal("stack"),
  id: z.string(),
  title: z.string().optional(),
  kind: z.enum(["stack", "queue", "calls"]),
  items: z.array(z.object({ id: z.number(), v: z.string(), tone })),
});

const ItemsViewSchema = z.object({
  t: z.literal("items"),
  id: z.string(),
  title: z.string().optional(),
  items: z.array(z.object({ v: z.string(), tone })),
});

const ListViewSchema = z.object({
  t: z.literal("list"),
  id: z.string(),
  title: z.string().optional(),
  nodes: z.array(
    z.object({
      id: z.number(),
      v: z.string(),
      x: z.number(),
      y: z.number(),
      next: z.number().optional(),
      rand: z.number().optional(),
      tone,
    }),
  ),
  ptrs: z.array(z.object({ name: z.string(), at: z.number().nullable() })).optional(),
  rows: z.array(z.string()).optional(),
});

const TreeViewSchema = z.object({
  t: z.literal("tree"),
  id: z.string(),
  title: z.string().optional(),
  nodes: z.array(
    z.object({
      id: z.number(),
      v: z.string(),
      l: z.number().optional(),
      r: z.number().optional(),
      kids: z.array(z.number()).optional(),
      tone,
      badge: z.string().optional(),
      end: z.boolean().optional(),
    }),
  ),
  roots: z.array(z.number()),
  ptrs: z.array(z.object({ name: z.string(), at: z.number() })).optional(),
  shape: z.enum(["circle", "box"]).optional(),
});

const GraphViewSchema = z.object({
  t: z.literal("graph"),
  id: z.string(),
  title: z.string().optional(),
  directed: z.boolean().optional(),
  nodes: z.array(
    z.object({
      id: z.string(),
      v: z.string(),
      x: z.number(),
      y: z.number(),
      tone,
      badge: z.string().optional(),
    }),
  ),
  edges: z.array(z.object({ a: z.string(), b: z.string(), w: z.string().optional(), tone })),
});

const GridViewSchema = z.object({
  t: z.literal("grid"),
  id: z.string(),
  title: z.string().optional(),
  cells: z.array(z.array(z.object({ v: z.string(), tone }))),
  rows: z.array(z.string()).optional(),
  cols: z.array(z.string()).optional(),
  ptrs: z.array(z.object({ name: z.string(), r: z.number(), c: z.number() })).optional(),
});

const IntervalsViewSchema = z.object({
  t: z.literal("intervals"),
  id: z.string(),
  title: z.string().optional(),
  rows: z.array(
    z.object({
      label: z.string(),
      items: z.array(z.object({ a: z.number(), b: z.number(), tone })),
    }),
  ),
  marks: z.array(z.object({ x: z.number(), label: z.string() })).optional(),
  min: z.number().optional(),
  max: z.number().optional(),
});

const BitsViewSchema = z.object({
  t: z.literal("bits"),
  id: z.string(),
  title: z.string().optional(),
  rows: z.array(z.object({ label: z.string(), bits: z.string(), v: z.string(), tone })),
  hi: z.array(z.number()).optional(),
});

const VarsViewSchema = z.object({
  t: z.literal("vars"),
  id: z.string(),
  items: z.array(z.object({ k: z.string(), v: z.string(), changed: z.boolean().optional() })),
});

const OpsViewSchema = z.object({
  t: z.literal("ops"),
  id: z.string(),
  items: z.array(
    z.object({
      call: z.string(),
      ret: z.string().optional(),
      state: z.enum(["todo", "cur", "done"]),
    }),
  ),
});

export const ViewSchema = z.discriminatedUnion("t", [
  ArrayViewSchema,
  MapViewSchema,
  StackViewSchema,
  ItemsViewSchema,
  ListViewSchema,
  TreeViewSchema,
  GraphViewSchema,
  GridViewSchema,
  IntervalsViewSchema,
  BitsViewSchema,
  VarsViewSchema,
  OpsViewSchema,
]);

export const StepSchema = z.object({
  line: z.number().int().nonnegative(),
  text: z.string().min(1),
  views: z.array(ViewSchema),
  final: z.boolean().optional(),
});

export const DifficultySchema = z.enum(["Easy", "Medium", "Hard"]);

export const LessonSchema = z.object({
  id: z.number().int().positive(),
  number: z.number().int().positive(),
  title: z.string().min(1),
  slug: z.string().min(1),
  category: z.string().min(1),
  difficulty: DifficultySchema,
  url: z.string().url(),
  pattern: z.string(),
  statement: z.string().min(1),
  example: z.object({ input: z.string(), output: z.string(), why: z.string() }),
  more: z.array(z.object({ input: z.string(), output: z.string() })),
  idea: z.array(z.string()).min(1),
  code: z.string().min(1),
  complexity: z.object({
    time: z.string(),
    timeWhy: z.string(),
    space: z.string(),
    spaceWhy: z.string(),
  }),
  steps: z.array(StepSchema).min(5),
});

export type Lesson = z.infer<typeof LessonSchema>;
export type Step = z.infer<typeof StepSchema>;
export type View = z.infer<typeof ViewSchema>;
export type Difficulty = z.infer<typeof DifficultySchema>;

export type ArrayView = z.infer<typeof ArrayViewSchema>;
export type MapView = z.infer<typeof MapViewSchema>;
export type StackView = z.infer<typeof StackViewSchema>;
export type ItemsView = z.infer<typeof ItemsViewSchema>;
export type ListView = z.infer<typeof ListViewSchema>;
export type TreeView = z.infer<typeof TreeViewSchema>;
export type GraphView = z.infer<typeof GraphViewSchema>;
export type GridView = z.infer<typeof GridViewSchema>;
export type IntervalsView = z.infer<typeof IntervalsViewSchema>;
export type BitsView = z.infer<typeof BitsViewSchema>;
export type VarsView = z.infer<typeof VarsViewSchema>;
export type OpsView = z.infer<typeof OpsViewSchema>;

/** Views drawn inside the 3D stage (the rest are HTML panels beside the code). */
export type SceneView = Exclude<View, VarsView | OpsView>;

export function isSceneView(view: View): view is SceneView {
  return view.t !== "vars" && view.t !== "ops";
}

export interface LessonMeta {
  id: number;
  number: number;
  title: string;
  slug: string;
  category: string;
  difficulty: Difficulty;
  /** the technique, e.g. "Hash map lookup" (searchable on the home page) */
  pattern: string;
}
